{"path": "task.py", "content": "def stack_machine(instructions):
    stack = []
    for instr in instructions:
        op = instr[0]
        if op == 'push':
            stack.append(instr[1])
        elif op == 'add':
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif op == 'multiply':
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif op == 'negate':
            a = stack.pop()
            stack.append(-a)
        else:
            raise ValueError(f"Unknown instruction {op}")
    if len(stack) != 1:
        raise ValueError("Stack must contain exactly one value")
    return stack[0]"}

