{"path": "task.py", "content": "def bencode_int(data):
    if not isinstance(data, bytes):
        raise TypeError("Expected bytes")
    if len(data) < 2 or data[0] != ord('i') or data[-1] != ord('e'):
        raise ValueError("Invalid bencode integer")
    inner = data[1:-1]
    if not inner:
        raise ValueError("Empty integer")
    # Check for negative zero
    if inner == b'-0':
        raise ValueError("negative zero")
    # Check for leading zero
    if inner[0] == ord('-'):
        num = inner[1:]
        if not num:
            raise ValueError("Invalid integer")
        if num[0] == ord('0') and len(num) > 1:
            raise ValueError("leading zero")
    else:
        if inner[0] == ord('0') and len(inner) > 1:
            raise ValueError("leading zero")
    # Convert to int
    return int(inner.decode())
"}

