{"path": "task.py", "content": "def connected_components(nodes, edges):
    # Build adjacency list
    adj = {node: [] for node in nodes}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = set()
    components = []
    for node in nodes:
        if node not in visited:
            stack = [node]
            visited.add(node)
            comp = []
            while stack:
                cur = stack.pop()
                comp.append(cur)
                for neighbor in adj[cur]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
            comp.sort()
            components.append(comp)
    components.sort(key=lambda x: x[0] if x else None)
    return components"}

