def permutation_rank(*args, **kwargs):
    if args:
        perm = args[0]
    else:
        perm = []
    n = len(perm)
    rank = 0
    for i in range(n):
        cnt = 0
        for j in range(i+1, n):
            if perm[j] < perm[i]:
