def zigzag_walk(*args):
    rows = args[0]
    columns = args[1]
    result = []
    for i in range(rows):
        if i % 2 == 0:
            for j in range(columns):
                result.append((i, j))
        else:
            for j in range(columns - 1, -1, -1):
                result.append((i, j))
    return result
